    "mainHtml": "<section class=\"sars-section sars-cta sars-grid-bg--light\" data-nav-theme=\"light\" aria-labelledby=\"contact-title\">\n        <div class=\"sars-container sars-cta__inner\">\n          <div class=\"sars-cta__copy\">\n            <p class=\"sars-kicker\">Contact</p>\n            <h1 id=\"contact-title\" class=\"sars-heading-xl\">Have an ambitious idea?</h1>\n            <p class=\"sars-heading-md\">Let's build what's next.</p>\n            <a class=\"sars-cta__mail\" href=\"mailto:business@sarsglobal.io\">business@sarsglobal.io</a>\n            <div class=\"sars-office-card\">\n              <p><span>Office location</span><strong>Main Office &mdash; Alwar</strong></p>\n              <address>Plot No. 43, Scheme No. 02, Vijay Commercial Complex, Bhagat Singh Circle, near Jai Marg, Alwar, Rajasthan 301001</address>\n              <a class=\"sars-location-link\" href=\"https://www.google.com/maps/search/?api=1&query=Plot%20No.%2043%2C%20Scheme%20No.%2002%2C%20Vijay%20Commercial%20Complex%2C%20Bhagat%20Singh%20Circle%2C%20near%20Jai%20Marg%2C%20Alwar%2C%20Rajasthan%20301001\" target=\"_blank\" rel=\"noopener noreferrer\">View on Google Maps &rarr;</a>\n            </div>\n            <div class=\"sars-office-card\">\n              <p><span>Office location</span><strong>Gurugram Office</strong></p>\n              <address>402, 2nd Floor, Pink Town House Market, Opp. U-25/12 Road, DLF Phase III, Nathupur, Sector 24, Gurugram, Haryana 122002</address>\n              <a class=\"sars-location-link\" href=\"https://www.google.com/maps/search/?api=1&query=402%2C%202nd%20Floor%2C%20Pink%20Town%20House%20Market%2C%20Opp.%20U-25%2F12%20Road%2C%20DLF%20Phase%20III%2C%20Nathupur%2C%20Sector%2024%2C%20Gurugram%2C%20Haryana%20122002\" target=\"_blank\" rel=\"noopener noreferrer\">View on Google Maps &rarr;</a>\n            </div>\n            <figure class=\"sars-cta__visual\">\n              <img src=\"/wp-content/uploads/2026/08/ChatGPT-Image-Aug-3-2026-06_53_26-PM.png\" alt=\"SARS Global contact visual\" loading=\"eager\" decoding=\"async\" fetchpriority=\"high\">\n            </figure>\n          </div>\n          <form class=\"sars-form\" data-contact-form novalidate>\n            <div class=\"sars-field\"><label for=\"name\">Name</label><input id=\"name\" name=\"name\" autocomplete=\"name\" required><span class=\"sars-field__error\">Enter your name.</span></div>\n            <div class=\"sars-field\"><label for=\"company\">Company</label><input id=\"company\" name=\"company\" autocomplete=\"organization\" required><span class=\"sars-field__error\">Enter your company.</span></div>\n            <div class=\"sars-field\"><label for=\"email\">Work email</label><input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required><span class=\"sars-field__error\">Enter a valid work email.</span></div>\n            <div class=\"sars-field\"><label for=\"phone\">Phone</label><input id=\"phone\" name=\"phone\" type=\"tel\" autocomplete=\"tel\" required><span class=\"sars-field__error\">Enter your phone number.</span></div>\n            <div class=\"sars-field\"><label for=\"service\">Service required</label><select id=\"service\" name=\"service\" required><option value=\"\">Select a service</option><option>Digital Marketing</option><option>Creative & Ad Film Production</option><option>UI/UX & Product Design</option><option>Software Development</option><option>Artificial Intelligence & Automation</option><option>Technology Consulting</option></select><span class=\"sars-field__error\">Choose a service.</span></div>\n            <div class=\"sars-field\"><label for=\"budget\">Estimated budget</label><select id=\"budget\" name=\"budget\" required><option value=\"\">Select range</option><option>Discovery first</option><option>Under $10k</option><option>$10k - $25k</option><option>$25k - $75k</option><option>$75k+</option></select><span class=\"sars-field__error\">Choose a budget range.</span></div>\n            <div class=\"sars-field\"><label for=\"details\">Project details</label><textarea id=\"details\" name=\"details\" required></textarea><span class=\"sars-field__error\">Share a few details.</span></div>\n            <label class=\"sars-checkbox\"><input type=\"checkbox\" name=\"consent\" required><span>I consent to SARS Global contacting me about this project.</span></label>\n            <button class=\"sars-button sars-button--dark\" type=\"submit\" data-magnetic>Start a Project</button>\n            <p class=\"sars-form__status\" data-form-status aria-live=\"polite\"></p>\n          </form>\n        </div>\n      </section>",
