    "ogDescription": "Learn how social search SEO helps brands become discoverable on Instagram, LinkedIn, YouTube, TikTok, Reddit and AI-powered discovery platforms in 2026.",
    "ogImage": "https://sarsglobal.io/assets/img/sars-new-logo.png",
    "twitterTitle": "Social Search SEO in 2026: How to Make Your Brand Discoverable on Instagram, LinkedIn & YouTube | SARS Global",
